INSERT INTO lessons (course_id, sort_order, title_ko, lesson_type, content, estimated_seconds) VALUES
('c1000000-0000-0000-0000-000000000006', 1, 'SDLC 개요', 'flashcard', '{"cards":[{"front":"SDLC란 무엇인가?","back":"소프트웨어 개발 생명주기(Software Development Life Cycle)로, 소프트웨어를 계획하고 개발하여 유지보수하는 전체 과정을 단계별로 정의한 프레임워크이다.","hint":null},{"front":"요구분석 단계의 주요 활동은?","back":"이해관계자의 요구사항을 수집하고 분석하여 문서화하는 단계이다. 기능적 요구사항과 비기능적 요구사항을 정의하며, SRS(소프트웨어 요구사항 명세서)를 작성한다.","hint":"SRS 문서 작성"},{"front":"설계 단계에서 무엇을 산출하는가?","back":"시스템 아키텍처, 데이터베이스 설계, UI/UX 설계 등을 산출한다. 상위 설계(High-Level Design)와 하위 설계(Low-Level Design)로 나뉜다.","hint":"아키텍처 및 상세 설계"},{"front":"테스트 단계의 목적은?","back":"개발된 소프트웨어가 요구사항을 충족하는지 검증하는 단계이다. 단위 테스트, 통합 테스트, 시스템 테스트, 인수 테스트 순으로 진행된다.","hint":"결함 발견 및 품질 검증"},{"front":"유지보수 단계의 유형 4가지는?","back":"수정(Corrective) 유지보수: 결함 수정, 적응(Adaptive) 유지보수: 환경 변화 대응, 완전(Perfective) 유지보수: 기능 개선, 예방(Preventive) 유지보수: 미래 결함 예방","hint":"수정/적응/완전/예방"}]}', 600),

('c1000000-0000-0000-0000-000000000006', 2, '애자일 vs 워터폴', 'quiz', '{"questions":[{"question":"워터폴 방법론의 가장 큰 특징은 무엇인가?","code":null,"options":["각 단계가 순차적으로 진행되며 이전 단계로 돌아가기 어렵다","반복적인 스프린트 주기를 사용한다","고객 피드백을 매 주기마다 반영한다","팀 자율성을 극대화한다"],"correct_index":0,"explanation":"워터폴은 요구분석→설계→구현→테스트→배포가 순차적으로 진행되는 선형 모델로, 한 단계가 완료되어야 다음 단계로 이동할 수 있다."},{"question":"애자일 방법론이 워터폴보다 유리한 상황은?","code":null,"options":["요구사항이 초기에 완전히 확정된 경우","규제가 엄격하여 문서화가 필수인 경우","요구사항이 자주 변경되는 프로젝트","하드웨어 의존성이 높은 프로젝트"],"correct_index":2,"explanation":"애자일은 변화하는 요구사항에 유연하게 대응할 수 있도록 설계되었으며, 짧은 반복 주기를 통해 고객 피드백을 빠르게 반영한다."},{"question":"애자일 선언문(Agile Manifesto)에서 강조하는 가치가 아닌 것은?","code":null,"options":["프로세스와 도구보다 개인과 상호작용","포괄적인 문서보다 작동하는 소프트웨어","계약 협상보다 고객과의 협력","변화 대응보다 계획 준수"],"correct_index":3,"explanation":"애자일 선언문은 계획 준수보다 변화 대응을 더 가치 있게 여긴다. 나머지 세 항목은 애자일 선언문의 핵심 가치이다."},{"question":"워터폴 방법론이 적합한 프로젝트 유형은?","code":null,"options":["스타트업의 MVP 개발","요구사항이 명확하고 변경이 거의 없는 정부 시스템","소셜 미디어 플랫폼 개발","모바일 앱 프로토타입 개발"],"correct_index":1,"explanation":"워터폴은 요구사항이 초기에 명확히 정의되고 변경 가능성이 낮은 프로젝트에 적합하다. 정부나 국방 시스템 같은 경우가 대표적이다."},{"question":"스프린트(Sprint)는 어느 방법론의 개념인가?","code":null,"options":["워터폴","V-모델","스크럼(애자일)","프로토타입 모델"],"correct_index":2,"explanation":"스프린트는 스크럼 프레임워크의 핵심 개념으로, 보통 1~4주 단위의 반복 개발 주기를 의미한다. 애자일 방법론의 일부이다."}]}', 720),

('c1000000-0000-0000-0000-000000000006', 3, '스크럼 프레임워크', 'flashcard', '{"cards":[{"front":"스프린트(Sprint)란?","back":"스크럼에서 정해진 기간(보통 1~4주) 동안 특정 목표를 달성하기 위해 작업하는 반복 개발 주기이다. 각 스프린트 끝에는 잠재적으로 출시 가능한 제품 증분이 만들어진다.","hint":"반복 개발 주기"},{"front":"제품 백로그(Product Backlog)란?","back":"제품에 필요한 모든 기능, 개선사항, 버그 수정 등을 우선순위에 따라 정렬한 목록이다. 제품 오너(Product Owner)가 관리하며, 지속적으로 업데이트된다.","hint":"우선순위화된 작업 목록"},{"front":"데일리 스탠드업(Daily Standup)의 세 가지 질문은?","back":"1. 어제 무엇을 했는가? 2. 오늘 무엇을 할 것인가? 3. 진행을 방해하는 장애물이 있는가? 15분 이내로 진행되는 짧은 일일 회의이다.","hint":"어제/오늘/장애물"},{"front":"스크럼 마스터(Scrum Master)의 역할은?","back":"팀이 스크럼 프로세스를 올바르게 따르도록 돕는 서번트 리더이다. 팀의 장애물을 제거하고, 스크럼 이벤트를 촉진하며, 팀 외부와의 소통을 지원한다.","hint":"서번트 리더, 장애물 제거"},{"front":"스프린트 회고(Sprint Retrospective)의 목적은?","back":"스프린트가 끝난 후 팀이 모여 잘된 점, 개선할 점, 실행할 행동 계획을 논의하는 회의이다. 지속적인 프로세스 개선을 목표로 한다.","hint":"프로세스 개선 회의"}]}', 600),

('c1000000-0000-0000-0000-000000000006', 4, '칸반 방법론', 'quiz', '{"questions":[{"question":"칸반에서 WIP(Work In Progress) 제한의 목적은?","code":null,"options":["팀원 수를 제한하기 위해","동시에 진행 중인 작업 수를 제한하여 흐름을 개선하기 위해","완료된 작업을 기록하기 위해","스프린트 기간을 정하기 위해"],"correct_index":1,"explanation":"WIP 제한은 각 단계에서 동시에 진행할 수 있는 작업 수를 제한함으로써 병목현상을 발견하고 작업 흐름을 개선하는 데 목적이 있다."},{"question":"칸반 보드의 기본 열(Column) 구성은?","code":null,"options":["계획→개발→배포","할 일(To Do)→진행 중(In Progress)→완료(Done)","백로그→스프린트→릴리즈","요구사항→설계→구현"],"correct_index":1,"explanation":"칸반 보드의 기본 구성은 할 일, 진행 중, 완료의 세 열이며, 팀의 워크플로우에 따라 더 세분화할 수 있다."},{"question":"칸반의 풀 시스템(Pull System)이란?","code":null,"options":["관리자가 팀원에게 작업을 배정하는 방식","팀원이 이전 작업을 완료했을 때 스스로 다음 작업을 가져오는 방식","외부 요청에 의해 작업이 시작되는 방식","자동화 도구가 작업을 할당하는 방식"],"correct_index":1,"explanation":"풀 시스템은 작업자가 현재 작업을 완료한 후 자발적으로 다음 작업을 가져오는 방식으로, 과부하를 방지하고 흐름을 최적화한다."},{"question":"스크럼과 칸반의 가장 큰 차이점은?","code":null,"options":["칸반은 개발에만 사용되고 스크럼은 전 단계에 사용된다","스크럼은 고정된 반복 주기(스프린트)를 사용하지만 칸반은 지속적인 흐름을 사용한다","칸반은 팀 역할이 엄격히 정해져 있다","스크럼은 WIP 제한을 사용하지 않는다"],"correct_index":1,"explanation":"스크럼은 스프린트라는 고정된 반복 주기를 기반으로 하지만, 칸반은 지속적인 흐름을 강조하며 고정된 반복 주기가 없다."},{"question":"리드 타임(Lead Time)과 사이클 타임(Cycle Time)의 차이는?","code":null,"options":["리드 타임은 작업 시작부터 완료까지, 사이클 타임은 요청부터 완료까지이다","리드 타임은 요청부터 완료까지, 사이클 타임은 작업 시작부터 완료까지이다","둘은 동일한 개념이다","리드 타임은 배포 시간만 측정한다"],"correct_index":1,"explanation":"리드 타임은 작업 요청 시점부터 완료까지의 전체 시간이며, 사이클 타임은 실제 작업을 시작한 시점부터 완료까지의 시간이다."}]}', 720),

('c1000000-0000-0000-0000-000000000006', 5, 'Git 기초 명령어', 'fill_blank', '{"questions":[{"question":"작업 디렉토리의 변경 파일을 스테이징 영역에 추가하는 명령어는?","code":"git ___ index.html","options":["add","commit","push","init"],"correct_index":0,"explanation":"git add 명령어는 변경된 파일을 스테이징 영역(Index)에 추가한다. git add . 으로 모든 변경 파일을 한번에 추가할 수 있다."},{"question":"스테이징된 변경사항을 로컬 저장소에 저장하는 명령어는?","code":"git ___ -m \"기능 추가\"","options":["commit","push","save","merge"],"correct_index":0,"explanation":"git commit은 스테이징 영역의 변경사항을 로컬 저장소에 영구적으로 저장한다. -m 옵션으로 커밋 메시지를 작성한다."},{"question":"로컬 브랜치를 원격 저장소에 업로드하는 명령어는?","code":"git ___ origin main","options":["push","pull","fetch","send"],"correct_index":0,"explanation":"git push는 로컬 저장소의 커밋을 원격 저장소로 전송한다. origin은 원격 저장소의 별칭이며 main은 브랜치 이름이다."},{"question":"원격 저장소의 변경사항을 로컬에 가져와 병합하는 명령어는?","code":"git ___ origin main","options":["pull","fetch","clone","sync"],"correct_index":0,"explanation":"git pull은 원격 저장소에서 변경사항을 가져와(fetch) 현재 브랜치에 자동으로 병합(merge)한다. fetch와 merge의 조합이다."},{"question":"새로운 브랜치를 생성하고 즉시 전환하는 명령어는?","code":"git ___ -b feature/login","options":["checkout","branch","switch","create"],"correct_index":0,"explanation":"git checkout -b 브랜치명은 새 브랜치를 생성하고 즉시 그 브랜치로 전환한다. 최신 Git에서는 git switch -c 브랜치명을 권장한다."}]}', 720),

('c1000000-0000-0000-0000-000000000006', 6, '브랜치 전략', 'quiz', '{"questions":[{"question":"Git Flow 전략에서 핵심 브랜치 2개는?","code":null,"options":["main과 develop","feature와 hotfix","release와 support","staging과 production"],"correct_index":0,"explanation":"Git Flow에서 main(또는 master)과 develop이 영구적인 핵심 브랜치이다. main은 출시 코드, develop은 다음 릴리즈를 위한 개발 코드를 포함한다."},{"question":"Trunk Based Development의 핵심 원칙은?","code":null,"options":["장기 기능 브랜치를 활용한다","모든 개발자가 하나의 메인 브랜치에 자주 커밋한다","릴리즈마다 별도 브랜치를 유지한다","핫픽스 전용 브랜치를 항상 유지한다"],"correct_index":1,"explanation":"Trunk Based Development는 모든 개발자가 하루에 최소 한 번 이상 메인 브랜치(trunk)에 직접 커밋하거나 매우 짧은 수명의 피처 브랜치를 사용하는 전략이다."},{"question":"GitHub Flow에서 작업 흐름의 순서는?","code":null,"options":["main→develop→feature→release→hotfix","main에서 브랜치 생성→커밋→PR 생성→리뷰→병합","feature→develop→release→main","브랜치→스테이징→QA→프로덕션"],"correct_index":1,"explanation":"GitHub Flow는 단순한 전략으로: main에서 브랜치를 만들고, 커밋 후 PR을 열어 리뷰받고, 승인되면 main에 병합한다."},{"question":"프로덕션 버그를 긴급 수정할 때 Git Flow에서 사용하는 브랜치는?","code":null,"options":["feature 브랜치","develop 브랜치","hotfix 브랜치","release 브랜치"],"correct_index":2,"explanation":"Git Flow에서 hotfix 브랜치는 프로덕션(main)에서 직접 분기하여 긴급 버그를 수정하고, 수정 후 main과 develop 모두에 병합된다."},{"question":"소규모 팀이나 CI/CD를 강조하는 환경에 가장 적합한 브랜치 전략은?","code":null,"options":["Git Flow","GitHub Flow 또는 Trunk Based Development","SVN 방식","릴리즈 브랜치 전략"],"correct_index":1,"explanation":"GitHub Flow나 Trunk Based Development는 단순하고 빠른 배포를 지원하여 소규모 팀이나 지속적 배포 환경에 적합하다. Git Flow는 릴리즈 주기가 명확한 대형 프로젝트에 더 적합하다."}]}', 720),

('c1000000-0000-0000-0000-000000000006', 7, 'PR과 코드 리뷰', 'flashcard', '{"cards":[{"front":"풀 리퀘스트(Pull Request)란?","back":"개발자가 자신의 브랜치에서 작업한 변경사항을 메인 브랜치에 병합해 달라고 요청하는 것이다. 코드 리뷰, 토론, 자동 테스트 실행의 기회를 제공한다.","hint":"병합 요청 및 리뷰 메커니즘"},{"front":"코드 리뷰의 주요 목적 3가지는?","back":"1. 버그 및 결함 조기 발견 2. 코드 품질 및 일관성 유지 3. 지식 공유 및 팀 학습 촉진. 리뷰는 코드를 공격하는 것이 아니라 함께 품질을 높이는 과정이다.","hint":"품질/지식/버그"},{"front":"효과적인 코드 리뷰 체크포인트는?","back":"기능 정확성, 엣지 케이스 처리, 코딩 컨벤션 준수, 보안 취약점, 성능 이슈, 테스트 커버리지, 코드 가독성 등을 확인한다.","hint":"정확성/보안/성능/가독성"},{"front":"건설적인 코드 리뷰 피드백 방법은?","back":"코드가 아닌 코드를 작성한 행위에 집중한다. ''이 코드는...'' 대신 ''이 부분을 이렇게 바꾸면 어떨까요?''처럼 제안 형태로 작성한다. 칭찬도 포함하고 이유를 명확히 설명한다.","hint":"제안 형태, 이유 설명"},{"front":"LGTM(Looks Good To Me)이란?","back":"코드 리뷰에서 사용하는 약어로 ''문제없어 보입니다''라는 뜻이다. 리뷰어가 변경사항을 승인할 때 사용한다. 단순히 통과가 아니라 충분히 검토했다는 의미이어야 한다.","hint":"리뷰 승인 표현"}]}', 600),

('c1000000-0000-0000-0000-000000000006', 8, '머지 전략 비교', 'quiz', '{"questions":[{"question":"git merge를 사용할 때 생성되는 특별한 커밋은?","code":null,"options":["태그 커밋","머지 커밋(Merge Commit)","스쿼시 커밋","체리픽 커밋"],"correct_index":1,"explanation":"git merge는 두 브랜치를 합칠 때 머지 커밋이라는 새로운 커밋을 생성한다. 이 커밋은 두 부모 커밋을 가지며, 히스토리에 분기와 병합이 명시적으로 남는다."},{"question":"git squash merge의 특징은?","code":null,"options":["모든 커밋 히스토리를 그대로 유지한다","피처 브랜치의 모든 커밋을 하나로 합쳐 메인 브랜치에 추가한다","커밋을 다른 브랜치 위에 재배치한다","충돌을 자동으로 해결한다"],"correct_index":1,"explanation":"squash merge는 피처 브랜치의 여러 커밋을 단 하나의 커밋으로 압축하여 병합한다. 메인 브랜치의 히스토리를 깔끔하게 유지할 수 있지만, 상세 커밋 이력은 사라진다."},{"question":"git rebase의 주요 목적은?","code":null,"options":["브랜치를 삭제한다","커밋 히스토리를 선형으로 만들기 위해 커밋을 다른 브랜치 위로 재배치한다","원격 저장소와 동기화한다","태그를 생성한다"],"correct_index":1,"explanation":"git rebase는 한 브랜치의 커밋들을 다른 브랜치의 최신 커밋 위에 재적용하여 선형적인 히스토리를 만든다. 히스토리가 깔끔해지지만 공유 브랜치에서는 위험할 수 있다."},{"question":"공유 브랜치(원격의 main)에서 rebase를 피해야 하는 이유는?","code":null,"options":["rebase가 느리기 때문에","다른 개발자의 히스토리와 충돌하여 커밋 해시가 변경되기 때문에","rebase는 로컬에서만 작동하기 때문에","merge commit이 생성되기 때문에"],"correct_index":1,"explanation":"rebase는 기존 커밋의 해시를 변경하므로, 이미 공유된 커밋에 rebase를 사용하면 다른 개발자의 히스토리와 충돌이 발생한다. 로컬 브랜치 정리에만 사용하는 것이 안전하다."},{"question":"팀이 메인 브랜치를 깔끔하게 유지하고 싶지만 피처 브랜치 개발 내역도 확인하고 싶다면?","code":null,"options":["squash merge를 사용한다","rebase만 사용한다","--no-ff 옵션을 사용한 merge를 사용한다","cherry-pick을 사용한다"],"correct_index":2,"explanation":"git merge --no-ff는 fast-forward가 가능해도 항상 머지 커밋을 생성하여 피처 브랜치의 존재를 히스토리에 명시적으로 남긴다. 기능 단위로 히스토리를 추적하기 용이하다."}]}', 720),

('c1000000-0000-0000-0000-000000000006', 9, 'CI/CD 개념', 'flashcard', '{"cards":[{"front":"CI(지속적 통합, Continuous Integration)란?","back":"개발자들이 코드 변경사항을 자주(하루에 여러 번) 메인 브랜치에 병합하는 관행이다. 병합 시마다 자동으로 빌드와 테스트가 실행되어 통합 문제를 조기에 발견한다.","hint":"자동 빌드 및 테스트"},{"front":"CD(지속적 배포, Continuous Deployment)와 지속적 전달(Continuous Delivery)의 차이는?","back":"지속적 전달(Delivery): 코드가 항상 배포 가능한 상태를 유지하지만 실제 프로덕션 배포는 수동 승인이 필요하다. 지속적 배포(Deployment): 모든 변경사항이 자동으로 프로덕션에 배포된다.","hint":"수동 승인 유무"},{"front":"CI/CD 파이프라인의 일반적인 단계는?","back":"코드 커밋→소스 코드 빌드→단위 테스트→코드 품질 검사(정적 분석)→통합 테스트→스테이징 배포→인수 테스트→프로덕션 배포 순으로 진행된다.","hint":"빌드→테스트→배포"},{"front":"CI/CD의 주요 이점은?","back":"1. 빠른 피드백: 버그를 즉시 발견 2. 배포 위험 감소: 작은 변경을 자주 배포 3. 개발 속도 향상: 반복 작업 자동화 4. 팀 협업 개선: 통합 충돌 최소화","hint":"빠른 피드백, 위험 감소"},{"front":"빌드 아티팩트(Build Artifact)란?","back":"CI 파이프라인에서 빌드 과정을 통해 생성된 결과물이다. JAR/WAR 파일, Docker 이미지, 실행 파일 등이 해당된다. 배포 단계에서 이 아티팩트를 사용한다.","hint":"빌드 결과물, Docker 이미지"}]}', 600),

('c1000000-0000-0000-0000-000000000006', 10, 'CI/CD 도구 비교', 'quiz', '{"questions":[{"question":"Jenkins의 가장 큰 특징은?","code":null,"options":["GitHub에서만 사용 가능하다","오픈소스이며 플러그인을 통해 높은 커스터마이징이 가능하다","클라우드 전용 서비스이다","GitLab과만 통합된다"],"correct_index":1,"explanation":"Jenkins는 오픈소스 CI/CD 도구로 2000개 이상의 플러그인을 통해 다양한 도구와 통합 가능하다. 자체 서버에 설치하여 운영하며 높은 유연성을 제공한다."},{"question":"GitHub Actions에서 워크플로우를 정의하는 파일 위치는?","code":null,"options":["/ci/workflows/ 디렉토리","루트의 Jenkinsfile",".github/workflows/ 디렉토리","/pipeline/ 디렉토리"],"correct_index":2,"explanation":"GitHub Actions의 워크플로우는 저장소의 .github/workflows/ 디렉토리에 YAML 파일로 정의한다. 파일명은 자유롭게 지정할 수 있다."},{"question":"GitLab CI/CD를 설정하기 위해 필요한 파일은?","code":null,"options":[".github/workflows/ci.yml","Jenkinsfile",".gitlab-ci.yml","circle.yml"],"correct_index":2,"explanation":"GitLab CI/CD는 저장소 루트에 위치한 .gitlab-ci.yml 파일로 파이프라인을 정의한다. stages, jobs, script 등의 키워드를 사용한다."},{"question":"GitHub Actions에서 재사용 가능한 작업 단위를 무엇이라 하는가?","code":null,"options":["플러그인(Plugin)","액션(Action)","스테이지(Stage)","파이프라인(Pipeline)"],"correct_index":1,"explanation":"GitHub Actions에서 액션(Action)은 재사용 가능한 개별 작업 단위이다. GitHub Marketplace에서 다른 개발자가 만든 액션을 가져다 사용할 수 있다."},{"question":"CI/CD 파이프라인에서 Self-hosted runner를 사용하는 주된 이유는?","code":null,"options":["항상 더 빠르기 때문에","보안 요구사항이나 특수한 환경(내부망, 특정 하드웨어) 때문에","무료로 제공되기 때문에","설정이 더 간단하기 때문에"],"correct_index":1,"explanation":"Self-hosted runner는 사내 보안 정책으로 코드가 외부로 나갈 수 없거나, 특수한 하드웨어(GPU 등)가 필요하거나, 내부 네트워크 접근이 필요한 경우에 사용한다."}]}', 720),

('c1000000-0000-0000-0000-000000000006', 11, '소프트웨어 테스트 종류', 'flashcard', '{"cards":[{"front":"단위 테스트(Unit Test)란?","back":"개별 함수, 메서드, 클래스 등 가장 작은 코드 단위를 독립적으로 테스트한다. 외부 의존성을 목(Mock)으로 대체하며, 빠르게 실행되고 작성이 쉽다. JUnit, pytest 등이 대표 도구이다.","hint":"최소 단위, 독립적 테스트"},{"front":"통합 테스트(Integration Test)란?","back":"여러 모듈이나 서비스가 함께 올바르게 동작하는지 테스트한다. 데이터베이스, 외부 API 등 실제 의존성과의 상호작용을 검증한다. 단위 테스트보다 느리지만 더 현실적이다.","hint":"모듈 간 상호작용 검증"},{"front":"E2E(End-to-End) 테스트란?","back":"실제 사용자 시나리오를 처음부터 끝까지 테스트한다. 브라우저를 통해 실제 UI를 조작하며 전체 시스템 흐름을 검증한다. Selenium, Cypress, Playwright 등이 대표 도구이다.","hint":"전체 사용자 시나리오"},{"front":"성능 테스트(Performance Test)와 부하 테스트(Load Test)의 차이는?","back":"성능 테스트: 시스템의 응답시간, 처리량 등 성능 지표를 측정한다. 부하 테스트: 예상되는 최대 사용자 수를 가정하여 시스템이 버티는지 확인한다. JMeter, k6, Locust 등이 사용된다.","hint":"성능 지표 측정 vs 한계 테스트"},{"front":"회귀 테스트(Regression Test)란?","back":"새로운 코드 변경이 기존에 정상 작동하던 기능을 망가뜨리지 않았는지 확인하는 테스트이다. CI/CD 파이프라인에서 자동으로 실행되어 기존 기능의 안정성을 보장한다.","hint":"기존 기능 보호"}]}', 600),

('c1000000-0000-0000-0000-000000000006', 12, 'TDD(테스트 주도 개발)', 'quiz', '{"questions":[{"question":"TDD의 핵심 사이클 순서는?","code":null,"options":["Green→Red→Refactor","Red→Green→Refactor","Refactor→Red→Green","Write→Test→Deploy"],"correct_index":1,"explanation":"TDD는 Red(실패하는 테스트 작성)→Green(테스트를 통과하는 최소한의 코드 작성)→Refactor(코드 개선) 순서를 반복한다."},{"question":"TDD에서 Red 단계의 의미는?","code":null,"options":["코드에 오류가 있어 수정이 필요하다","아직 구현되지 않은 기능에 대한 실패하는 테스트를 먼저 작성한다","리팩토링 후 테스트가 실패했다","배포 전 검증 단계이다"],"correct_index":1,"explanation":"Red 단계에서는 구현하려는 기능의 테스트를 먼저 작성한다. 아직 기능이 구현되지 않았으므로 테스트는 실패(Red)한다. 이것이 TDD의 시작점이다."},{"question":"TDD의 주요 장점이 아닌 것은?","code":null,"options":["자연스럽게 높은 테스트 커버리지를 달성한다","코드 설계가 개선된다(테스트하기 쉬운 구조)","초기 개발 속도가 빨라진다","리팩토링 시 안전망을 제공한다"],"correct_index":2,"explanation":"TDD는 테스트를 먼저 작성하므로 초기 개발 속도는 느릴 수 있다. 하지만 장기적으로 버그 감소와 설계 개선으로 전체 개발 속도는 향상될 수 있다."},{"question":"TDD에서 Refactor 단계의 목적은?","code":null,"options":["테스트 코드를 삭제한다","Green 단계에서 작성한 최소 코드를 품질을 유지하면서 개선한다","새로운 기능을 추가한다","배포를 준비한다"],"correct_index":1,"explanation":"Refactor 단계에서는 테스트가 통과하는 상태를 유지하면서 코드의 가독성, 중복 제거, 구조 개선을 한다. 테스트가 안전망 역할을 한다."},{"question":"BDD(행동 주도 개발)와 TDD의 차이점은?","code":null,"options":["BDD는 테스트를 먼저 작성하지 않는다","BDD는 비즈니스 관점의 시나리오를 기반으로 테스트를 작성하며 Given-When-Then 형식을 사용한다","BDD는 단위 테스트만 작성한다","BDD는 개발자만 사용한다"],"correct_index":1,"explanation":"BDD는 TDD를 확장한 개념으로 ''주어진 조건에서(Given), 어떤 행동을 하면(When), 이런 결과가 나온다(Then)''형식으로 비즈니스 요구사항을 테스트로 표현한다."}]}', 720),

('c1000000-0000-0000-0000-000000000006', 13, '테스트 피라미드', 'quiz', '{"questions":[{"question":"테스트 피라미드에서 가장 하단(기반)에 위치하는 테스트 유형은?","code":null,"options":["E2E 테스트","통합 테스트","단위 테스트","수동 테스트"],"correct_index":2,"explanation":"테스트 피라미드의 하단에는 단위 테스트가 위치한다. 가장 수가 많아야 하며, 빠르고 저렴하게 실행된다. 전체 테스트의 70% 이상을 차지하는 것이 이상적이다."},{"question":"테스트 피라미드에서 E2E 테스트의 특성으로 올바른 것은?","code":null,"options":["가장 많은 수를 유지해야 한다","실행 속도가 매우 빠르다","작성 비용이 낮다","수가 적어야 하지만 가장 현실적인 검증을 제공한다"],"correct_index":3,"explanation":"E2E 테스트는 피라미드의 최상단에 위치하며 수가 적어야 한다. 실행이 느리고 유지보수 비용이 높지만 실제 사용자 시나리오를 검증하는 가장 현실적인 방법이다."},{"question":"테스트 아이스크림(Ice Cream) 안티패턴이란?","code":null,"options":["단위 테스트가 너무 많은 상태","E2E 테스트가 너무 많고 단위 테스트가 적은, 피라미드가 뒤집힌 상태","통합 테스트만 있는 상태","테스트가 전혀 없는 상태"],"correct_index":1,"explanation":"테스트 아이스크림은 테스트 피라미드의 안티패턴으로, E2E 테스트가 지나치게 많고 단위 테스트가 거의 없는 역삼각형 구조이다. 느리고 불안정한 테스트 스위트를 만든다."},{"question":"통합 테스트가 단위 테스트보다 느린 주요 이유는?","code":null,"options":["코드가 더 복잡하기 때문에","데이터베이스, 네트워크 등 실제 외부 의존성을 사용하기 때문에","테스트 코드 작성량이 많기 때문에","컴파일이 필요하기 때문에"],"correct_index":1,"explanation":"통합 테스트는 데이터베이스 연결, 네트워크 호출, 파일 시스템 접근 등 실제 I/O 작업을 포함하므로 단위 테스트보다 훨씬 느리다."},{"question":"테스트 커버리지(Test Coverage) 100%가 항상 좋은 것인가?","code":null,"options":["그렇다, 100%는 항상 목표가 되어야 한다","아니다, 커버리지보다 테스트 품질과 의미 있는 케이스 검증이 더 중요하다","커버리지는 측정할 필요가 없다","50%가 최적이다"],"correct_index":1,"explanation":"100% 커버리지를 위해 의미없는 테스트를 추가하는 것보다, 버그가 자주 발생하는 핵심 로직과 엣지 케이스를 집중적으로 테스트하는 것이 더 효과적이다."}]}', 720),

('c1000000-0000-0000-0000-000000000006', 14, '클린 코드 원칙', 'flashcard', '{"cards":[{"front":"클린 코드에서 좋은 명명 규칙이란?","back":"변수, 함수, 클래스 이름은 그 목적을 명확히 표현해야 한다. 축약어 사용을 자제하고, 검색 가능한 이름을 사용한다. 예: d(나쁨) → elapsedDays(좋음), getUserData() → fetchUserProfileById() (좋음)","hint":"의도를 드러내는 이름"},{"front":"함수는 얼마나 작아야 하는가?","back":"클린 코드에서 함수는 한 가지 일만 해야 하며(SRP), 가능한 짧아야 한다. 로버트 마틴은 20줄 이하, 들여쓰기 2단계 이하를 권장한다. 함수 이름만으로 동작을 이해할 수 있어야 한다.","hint":"한 가지 일, 짧게"},{"front":"주석을 최소화해야 하는 이유는?","back":"코드 자체가 문서가 되어야 한다. 나쁜 코드를 주석으로 설명하는 것은 지양한다. 코드가 바뀌면 주석이 뒤떨어질 수 있다. 예외: 공개 API의 Javadoc, 법적 주석, 의도 설명이 꼭 필요한 경우는 허용된다.","hint":"코드가 곧 문서"},{"front":"일관된 코드 포맷팅이 중요한 이유는?","back":"팀 전체가 동일한 포맷팅 규칙을 따르면 코드 가독성이 높아지고 코드 리뷰 시 실질적인 내용에 집중할 수 있다. ESLint, Prettier, Black 같은 도구로 자동화하는 것이 좋다.","hint":"팀 일관성, 자동화"},{"front":"DRY(Don''t Repeat Yourself) 원칙이란?","back":"코드 중복을 제거하는 원칙이다. 동일한 로직이 여러 곳에 있으면 변경 시 모든 곳을 수정해야 하므로 버그가 발생하기 쉽다. 공통 로직은 함수나 클래스로 추출하여 재사용한다.","hint":"중복 제거, 재사용"}]}', 600),

('c1000000-0000-0000-0000-000000000006', 15, '코드 스멜', 'quiz', '{"questions":[{"question":"''긴 메서드(Long Method)'' 코드 스멜의 해결 방법은?","code":null,"options":["메서드에 더 많은 기능을 추가한다","메서드를 더 작은 단위로 추출(Extract Method)한다","주석을 추가하여 이해를 돕는다","변수명을 변경한다"],"correct_index":1,"explanation":"긴 메서드는 여러 책임을 가진다는 신호이다. 논리적으로 그룹화된 코드 블록을 별도의 메서드로 추출하여 각 메서드가 한 가지 일만 하도록 분리해야 한다."},{"question":"''큰 클래스(God Class/Large Class)'' 코드 스멜이 나타내는 문제는?","code":null,"options":["클래스가 너무 많은 책임을 갖고 있어 단일 책임 원칙(SRP)을 위반한다","클래스의 파일 크기가 크다","클래스가 인터페이스를 구현하지 않는다","클래스에 생성자가 없다"],"correct_index":0,"explanation":"큰 클래스(God Class)는 너무 많은 필드, 메서드, 책임을 가진 클래스이다. SRP(단일 책임 원칙)를 위반하며, 클래스를 여러 작은 클래스로 분리해야 한다."},{"question":"''기능 편애(Feature Envy)'' 코드 스멜이란?","code":null,"options":["클래스가 자신의 데이터보다 다른 클래스의 데이터를 더 많이 사용하는 메서드","클래스가 너무 많은 기능을 가진 경우","메서드가 매개변수를 너무 많이 받는 경우","중복 코드가 존재하는 경우"],"correct_index":0,"explanation":"기능 편애는 어떤 메서드가 자신이 속한 클래스의 데이터보다 다른 클래스의 데이터와 메서드를 더 많이 사용할 때 발생한다. 해당 메서드를 데이터가 있는 클래스로 이동하는 것이 해결책이다."},{"question":"''산탄총 수술(Shotgun Surgery)'' 코드 스멜이 위험한 이유는?","code":null,"options":["코드가 너무 길어서","하나의 변경사항을 위해 여러 클래스를 수정해야 하므로 누락 위험이 크다","테스트 작성이 불가능해서","컴파일 오류가 자주 발생해서"],"correct_index":1,"explanation":"산탄총 수술은 하나의 기능 변경이 많은 클래스에 분산되어 있을 때 발생한다. 변경 시 모든 관련 클래스를 수정해야 하며, 일부를 누락하면 버그가 발생한다."},{"question":"''매직 넘버(Magic Number)'' 코드 스멜의 해결 방법은?","code":null,"options":["숫자를 더 큰 값으로 변경한다","의미 있는 이름의 상수(Constant)로 추출하여 대체한다","주석으로 숫자의 의미를 설명한다","숫자를 변수로 대체한다"],"correct_index":1,"explanation":"코드에 직접 사용된 의미 불분명한 숫자는 상수로 추출해야 한다. 예: if (age > 18) → final int LEGAL_AGE = 18; if (age > LEGAL_AGE) 처럼 의도를 명확히 한다."}]}', 720),

('c1000000-0000-0000-0000-000000000006', 16, '리팩토링 기법', 'fill_blank', '{"questions":[{"question":"중복된 코드 블록을 별도의 메서드로 분리하는 리팩토링 기법은?","code":"// Before\nvoid printInvoice() {\n    System.out.println(\"이름: \" + name);\n    System.out.println(\"금액: \" + amount);\n}\nvoid printReceipt() {\n    System.out.println(\"이름: \" + name);\n    System.out.println(\"금액: \" + amount);\n}\n\n// After: ___ Method 적용","options":["Extract","Inline","Move","Pull Up"],"correct_index":0,"explanation":"Extract Method(메서드 추출)는 코드 블록을 새로운 메서드로 분리하는 기법이다. 중복 제거와 가독성 향상에 효과적이며 가장 자주 사용되는 리팩토링 기법 중 하나이다."},{"question":"불필요하게 복잡한 메서드 호출을 직접 코드로 대체하는 리팩토링 기법은?","code":"// Before\nint getBasePrice() { return quantity * unitPrice; }\ndouble price = getBasePrice() * discount;\n\n// After: ___ Method 적용\ndouble price = (quantity * unitPrice) * discount;","options":["Inline","Extract","Rename","Replace"],"correct_index":0,"explanation":"Inline Method는 메서드 본문이 너무 단순하여 메서드 이름이 오히려 이해를 방해할 때 사용한다. 메서드 호출을 메서드 내용으로 직접 대체한다."},{"question":"변수나 메서드의 이름을 의미 있게 변경하는 리팩토링 기법은?","code":"// Before\nint d = 30; // 만료일까지 남은 일수\n\n// After: ___ Variable 적용\nint ___ = 30;","options":["daysUntilExpiration","Rename","d2","tempDays"],"correct_index":0,"explanation":"Rename Variable/Method는 이름을 더 명확하고 의도를 잘 드러내도록 변경하는 기법이다. 코드의 자기 문서화(Self-documenting) 능력을 높이는 가장 간단한 리팩토링이다."},{"question":"조건문의 복잡한 로직을 메서드로 분리하는 기법은?","code":"if (date.before(SUMMER_START) || date.after(SUMMER_END)) {\n    charge = quantity * winterRate + winterServiceCharge;\n} else {\n    charge = quantity * summerRate;\n}\n\n// ___  Conditional 적용 후\nif (isNotSummer(date)) {\n    charge = winterCharge(quantity);\n} else {\n    charge = summerCharge(quantity);\n}","options":["Decompose","Inline","Extract","Simplify"],"correct_index":0,"explanation":"Decompose Conditional은 복잡한 조건문의 조건과 then/else 블록을 각각 메서드로 추출하는 기법이다. 조건의 의도를 명확히 표현할 수 있다."},{"question":"클래스 내부의 필드나 메서드를 부모 클래스로 이동시키는 리팩토링 기법은?","code":"class Animal {}\nclass Dog extends Animal {\n    String name;\n    void eat() { ... }\n}\nclass Cat extends Animal {\n    String name;\n    void eat() { ... }\n}\n// ___ Up Field/Method 적용 → Animal에 name, eat() 이동","options":["Pull","Push","Move","Extract"],"correct_index":0,"explanation":"Pull Up은 여러 서브클래스에 중복된 필드나 메서드를 부모 클래스로 올리는 기법이다. 반대로 Push Down은 부모의 요소를 특정 서브클래스로 내리는 기법이다."}]}', 720),

('c1000000-0000-0000-0000-000000000006', 17, '기술 부채', 'quiz', '{"questions":[{"question":"기술 부채(Technical Debt)의 정의로 가장 적합한 것은?","code":null,"options":["소프트웨어 개발에 필요한 실제 비용","빠른 개발을 위해 선택한 단기 해결책이 장기적으로 추가 작업을 필요로 하게 만드는 상태","프로젝트 예산 초과 비용","팀원이 배워야 할 새로운 기술들"],"correct_index":1,"explanation":"기술 부채는 Ward Cunningham이 제안한 개념으로, 지금 당장 빠른 방법을 선택하면 나중에 더 많은 노력(이자)을 지불해야 한다는 금융 비유이다."},{"question":"의도적 기술 부채(Deliberate Technical Debt)가 정당화되는 상황은?","code":null,"options":["팀원이 기술이 부족할 때","데드라인 압박으로 MVP를 빠르게 출시해야 할 때","무조건 정당화될 수 없다","테스트 작성이 귀찮을 때"],"correct_index":1,"explanation":"MVP(최소 기능 제품) 출시나 긴급한 시장 기회 대응을 위해 의도적으로 기술 부채를 감수하는 것은 비즈니스적으로 정당화될 수 있다. 단, 이후 반드시 상환 계획이 있어야 한다."},{"question":"기술 부채를 관리하는 가장 효과적인 방법은?","code":null,"options":["부채가 쌓일 때까지 무시한다","스프린트마다 일정 비율의 시간을 기술 부채 상환에 할당한다","새 프로젝트를 시작한다","팀원을 교체한다"],"correct_index":1,"explanation":"기술 부채는 완전히 없앨 수 없으므로, 스프린트마다 일정 시간(예: 20%)을 리팩토링과 기술 부채 상환에 할당하여 꾸준히 관리하는 것이 효과적이다."},{"question":"기술 부채가 팀에 미치는 영향이 아닌 것은?","code":null,"options":["새로운 기능 개발 속도 저하","버그 발생 빈도 증가","코드 이해 및 수정의 어려움 증가","팀원 수 증가"],"correct_index":3,"explanation":"기술 부채는 개발 속도 저하, 버그 증가, 코드 복잡도 증가, 개발자 사기 저하 등을 초래한다. 팀원 수 증가는 기술 부채의 직접적 결과가 아니다."},{"question":"보이 스카우트 규칙(Boy Scout Rule)이 기술 부채와 관련된 이유는?","code":null,"options":["코드를 절대 수정하지 말라는 원칙이기 때문에","코드를 볼 때마다 발견한 것보다 조금 더 깨끗하게 남기자는 원칙으로 기술 부채를 점진적으로 줄이기 때문에","새 기능 개발 전 리팩토링을 금지하기 때문에","기술 부채를 문서화하는 방법이기 때문에"],"correct_index":1,"explanation":"로버트 마틴이 제안한 보이 스카우트 규칙은 ''캠핑장을 처음 왔을 때보다 더 깨끗이 남겨라''에서 유래했다. 코드를 수정할 때마다 조금씩 개선하면 기술 부채가 점진적으로 감소한다."}]}', 720),

('c1000000-0000-0000-0000-000000000006', 18, '시스템 설계 기초', 'flashcard', '{"cards":[{"front":"확장성(Scalability)의 두 가지 유형은?","back":"수직 확장(Scale Up): 단일 서버의 CPU, RAM, 스토리지를 증가시킨다. 한계가 있고 비용이 높다. 수평 확장(Scale Out): 서버 대수를 늘린다. 비용 효율적이고 이론적으로 무한 확장 가능하지만 분산 시스템 복잡성이 증가한다.","hint":"Scale Up vs Scale Out"},{"front":"가용성(Availability)과 SLA란?","back":"가용성은 시스템이 정상 운영되는 시간의 비율이다. 99.9%(Three Nines)는 연간 약 8.7시간, 99.99%(Four Nines)는 약 52분의 다운타임을 허용한다. SLA(서비스 수준 협약)는 서비스 제공자가 보장하는 가용성 수준이다.","hint":"Three Nines, Four Nines"},{"front":"CAP 정리(CAP Theorem)란?","back":"분산 시스템은 일관성(Consistency), 가용성(Availability), 분할 내성(Partition Tolerance) 세 가지 중 동시에 두 가지만 완전히 보장할 수 있다는 이론이다. 실제로는 P(분할 내성)가 필수이므로 CP 또는 AP 중 선택한다.","hint":"일관성/가용성/분할 내성"},{"front":"로드 밸런서(Load Balancer)의 역할은?","back":"들어오는 네트워크 트래픽을 여러 서버에 분산시키는 장치이다. 라운드 로빈, 최소 연결, IP 해싱 등의 알고리즘을 사용한다. 단일 장애점(SPOF)을 제거하고 가용성을 높인다.","hint":"트래픽 분산, SPOF 제거"},{"front":"캐싱(Caching)이 시스템 성능에 기여하는 방법은?","back":"자주 접근하는 데이터를 빠른 저장소(메모리)에 보관하여 데이터베이스 부하를 줄이고 응답 시간을 단축한다. Redis, Memcached가 대표적이다. 캐시 만료 정책(TTL)과 캐시 무효화 전략이 중요하다.","hint":"자주 쓰는 데이터를 메모리에"}]}', 600),

('c1000000-0000-0000-0000-000000000006', 19, 'MSA vs 모놀리식', 'quiz', '{"questions":[{"question":"모놀리식 아키텍처의 가장 큰 장점은?","code":null,"options":["서비스별 독립 배포가 가능하다","개발, 테스트, 배포가 단순하며 초기 개발 속도가 빠르다","기술 스택을 서비스마다 다르게 선택할 수 있다","특정 서비스만 독립적으로 확장할 수 있다"],"correct_index":1,"explanation":"모놀리식은 하나의 애플리케이션으로 구성되므로 초기에는 개발과 배포가 단순하다. 소규모 팀이나 초기 스타트업에 적합하다."},{"question":"MSA(마이크로서비스 아키텍처)의 핵심 원칙은?","code":null,"options":["모든 서비스가 하나의 데이터베이스를 공유한다","각 서비스가 독립적으로 배포 가능하고 단일 비즈니스 기능에 집중한다","서비스 간 통신은 반드시 동기 방식이어야 한다","하나의 팀이 모든 서비스를 관리한다"],"correct_index":1,"explanation":"MSA는 각 서비스가 독립적으로 개발, 배포, 확장 가능하며 각자의 데이터베이스를 갖는다. 느슨한 결합(Loose Coupling)과 높은 응집도(High Cohesion)가 핵심이다."},{"question":"MSA로 전환을 고려해야 하는 적절한 시점은?","code":null,"options":["프로젝트 시작 단계부터","모놀리식이 팀 규모 증가, 배포 복잡성 증가로 개발 속도를 저하시킬 때","MSA가 더 현대적이므로 항상 MSA를 선택해야 한다","팀원이 10명 이하일 때"],"correct_index":1,"explanation":"MSA는 조직이 성장하고 모놀리식의 복잡성이 개발 속도를 저하시킬 때 전환을 고려한다. 초기부터 MSA를 적용하면 불필요한 복잡성이 증가한다."},{"question":"MSA에서 서비스 간 통신 방식 2가지는?","code":null,"options":["파일 공유와 데이터베이스 공유","동기 방식(REST/gRPC)과 비동기 방식(메시지 큐: Kafka, RabbitMQ)","SSH와 FTP","소켓과 파이프"],"correct_index":1,"explanation":"MSA에서 서비스 간 통신은 동기 방식(HTTP REST, gRPC)과 비동기 방식(Kafka, RabbitMQ 같은 메시지 브로커)으로 나뉜다. 비동기 방식은 느슨한 결합을 강화한다."},{"question":"MSA의 주요 단점은?","code":null,"options":["단일 장애점(SPOF) 위험이 높다","분산 시스템 복잡성 증가, 네트워크 지연, 데이터 일관성 관리 어려움이 있다","배포가 불가능하다","단일 기술 스택만 사용해야 한다"],"correct_index":1,"explanation":"MSA는 분산 시스템 관리 복잡성, 서비스 간 네트워크 통신 오버헤드, 분산 트랜잭션 처리의 어려움, 운영 인프라 복잡성 증가 등의 단점이 있다."}]}', 720),

('c1000000-0000-0000-0000-000000000006', 20, '소프트웨어 공학 종합 복습', 'quiz', '{"questions":[{"question":"스크럼에서 제품 오너(Product Owner)의 주된 역할은?","code":null,"options":["팀의 장애물을 제거한다","제품 백로그를 관리하고 비즈니스 가치에 따라 우선순위를 결정한다","스프린트 일정을 관리한다","코드 품질을 보장한다"],"correct_index":1,"explanation":"제품 오너는 제품 백로그를 소유하고, 이해관계자의 요구를 파악하여 기능의 우선순위를 결정한다. 스크럼 마스터가 프로세스를 지원하는 반면 제품 오너는 ''무엇을 만들지''를 결정한다."},{"question":"SOLID 원칙 중 단일 책임 원칙(SRP)이란?","code":null,"options":["하나의 클래스는 하나의 이유로만 변경되어야 한다","클래스는 확장에 열려있고 수정에 닫혀있어야 한다","하위 클래스는 상위 클래스를 대체할 수 있어야 한다","인터페이스는 클라이언트에 특화되어야 한다"],"correct_index":0,"explanation":"SRP(Single Responsibility Principle)는 하나의 클래스는 하나의 책임만 가져야 하며, 변경의 이유가 하나여야 한다는 원칙이다. 클린 코드와 리팩토링의 기반이 된다."},{"question":"DevOps의 핵심 목표는?","code":null,"options":["개발팀과 운영팀을 완전히 분리하여 전문성을 높인다","개발(Dev)과 운영(Ops)의 협업을 강화하여 소프트웨어 출시 주기를 단축하고 품질을 향상시킨다","운영 자동화만을 추구한다","개발자가 서버를 직접 관리하지 않도록 한다"],"correct_index":1,"explanation":"DevOps는 개발과 운영 팀 간의 사일로를 제거하고, 자동화, 협업, 지속적 개선을 통해 더 빠르고 안정적인 소프트웨어 전달을 목표로 한다."},{"question":"소프트웨어 아키텍처 패턴 중 레이어드(Layered) 아키텍처의 특징은?","code":null,"options":["모든 서비스가 독립적으로 배포된다","프레젠테이션, 비즈니스 로직, 데이터 접근 계층이 수직으로 분리되어 각 계층은 바로 아래 계층에만 의존한다","이벤트를 통해 서비스 간 통신한다","모든 컴포넌트가 동등한 관계이다"],"correct_index":1,"explanation":"레이어드 아키텍처는 UI/컨트롤러, 서비스/비즈니스 로직, 레포지토리/데이터 접근 계층으로 분리하는 가장 일반적인 패턴이다. 각 계층은 인접한 하위 계층에만 의존한다."},{"question":"소프트웨어 공학에서 ''릴리즈 초기에 자주 배포하라(Release Early, Release Often)''의 의미는?","code":null,"options":["품질 검증 없이 빠르게 배포한다","작은 변경사항을 자주 배포하여 피드백을 빠르게 받고 위험을 분산시킨다","한 번에 많은 기능을 묶어서 배포한다","배포 빈도는 품질과 무관하다"],"correct_index":1,"explanation":"빈번한 소규모 배포는 각 배포의 위험을 줄이고, 문제 발생 시 빠르게 원인을 찾을 수 있으며, 사용자 피드백을 신속하게 반영할 수 있다. CI/CD의 철학과 일치한다."}]}', 900);
